type InputTask = {
  id: string;
  duration: number;
  dependsOn: string[];
};

type Schedule = {
  order: string[];
  layers: string[][];
  earliest: Record<string, { start: number; finish: number }>;
  totalDuration: number;
  criticalPath: string[];
};

class CliError extends Error {}

function fail(message: string): never {
  throw new CliError(message);
}

function validate(input: unknown): InputTask[] {
  if (typeof input !== "object" || input === null || Array.isArray(input)) {
    fail("input must be a JSON object");
  }

  const root = input as Record<string, unknown>;
  if (!Array.isArray(root.tasks)) fail('"tasks" must be an array');

  const ids = new Set<string>();
  const tasks: InputTask[] = root.tasks.map((raw, index) => {
    const at = `tasks[${index}]`;
    if (typeof raw !== "object" || raw === null || Array.isArray(raw)) {
      fail(`${at} must be an object`);
    }

    const task = raw as Record<string, unknown>;
    if (typeof task.id !== "string" || task.id.length === 0) {
      fail(`${at}.id must be a non-empty string`);
    }
    if (ids.has(task.id)) fail(`duplicate task id: ${JSON.stringify(task.id)}`);
    ids.add(task.id);

    if (typeof task.duration !== "number" || !Number.isFinite(task.duration) || task.duration < 0) {
      fail(`${at}.duration must be a finite non-negative number`);
    }

    const dependsOn = task.dependsOn === undefined ? [] : task.dependsOn;
    if (!Array.isArray(dependsOn)) fail(`${at}.dependsOn must be an array`);
    const dependencies: string[] = [];
    const seen = new Set<string>();
    for (let dependencyIndex = 0; dependencyIndex < dependsOn.length; dependencyIndex++) {
      const dependency = dependsOn[dependencyIndex];
      if (typeof dependency !== "string") {
        fail(`${at}.dependsOn[${dependencyIndex}] must be a string`);
      }
      if (seen.has(dependency)) {
        fail(`${at}.dependsOn contains duplicate id: ${JSON.stringify(dependency)}`);
      }
      seen.add(dependency);
      dependencies.push(dependency);
    }

    return { id: task.id, duration: task.duration, dependsOn: dependencies };
  });

  for (const task of tasks) {
    for (const dependency of task.dependsOn) {
      if (dependency === task.id) fail(`task ${JSON.stringify(task.id)} cannot depend on itself`);
      if (!ids.has(dependency)) {
        fail(`task ${JSON.stringify(task.id)} depends on unknown task ${JSON.stringify(dependency)}`);
      }
    }
  }

  return tasks;
}

function comparePaths(a: string[], b: string[]): number {
  const length = Math.min(a.length, b.length);
  for (let i = 0; i < length; i++) {
    const comparison = a[i].localeCompare(b[i]);
    if (comparison !== 0) return comparison;
  }
  return a.length - b.length;
}

function findCycle(tasks: InputTask[]): string[] {
  const byId = new Map(tasks.map((task) => [task.id, task]));
  const state = new Map<string, 0 | 1 | 2>();
  const stack: string[] = [];
  const positions = new Map<string, number>();

  function visit(id: string): string[] | undefined {
    state.set(id, 1);
    positions.set(id, stack.length);
    stack.push(id);

    const dependencies = [...byId.get(id)!.dependsOn].sort((a, b) => a.localeCompare(b));
    for (const dependency of dependencies) {
      if (state.get(dependency) === 1) {
        return [...stack.slice(positions.get(dependency)!), dependency];
      }
      if (!state.get(dependency)) {
        const cycle = visit(dependency);
        if (cycle) return cycle;
      }
    }

    stack.pop();
    positions.delete(id);
    state.set(id, 2);
    return undefined;
  }

  for (const id of [...byId.keys()].sort((a, b) => a.localeCompare(b))) {
    if (!state.get(id)) {
      const cycle = visit(id);
      if (cycle) return cycle;
    }
  }
  return [];
}

function plan(tasks: InputTask[]): Schedule {
  const byId = new Map(tasks.map((task) => [task.id, task]));
  const dependents = new Map<string, string[]>(tasks.map((task) => [task.id, []]));
  const remaining = new Map<string, number>();

  for (const task of tasks) {
    remaining.set(task.id, task.dependsOn.length);
    for (const dependency of task.dependsOn) dependents.get(dependency)!.push(task.id);
  }
  for (const ids of dependents.values()) ids.sort((a, b) => a.localeCompare(b));

  const ready = tasks
    .filter((task) => task.dependsOn.length === 0)
    .map((task) => task.id)
    .sort((a, b) => a.localeCompare(b));
  const order: string[] = [];

  while (ready.length > 0) {
    const id = ready.shift()!;
    order.push(id);
    for (const dependent of dependents.get(id)!) {
      const count = remaining.get(dependent)! - 1;
      remaining.set(dependent, count);
      if (count === 0) {
        ready.push(dependent);
        ready.sort((a, b) => a.localeCompare(b));
      }
    }
  }

  if (order.length !== tasks.length) {
    const cycle = findCycle(tasks);
    fail(`dependency cycle: ${cycle.join(" -> ")}`);
  }

  const earliest: Record<string, { start: number; finish: number }> = {};
  const layerById = new Map<string, number>();
  const paths = new Map<string, string[]>();
  let totalDuration = 0;

  for (const id of order) {
    const task = byId.get(id)!;
    let start = 0;
    let layer = 0;
    let bestPrefix: string[] | undefined;

    for (const dependency of task.dependsOn) {
      const finish = earliest[dependency].finish;
      const candidate = paths.get(dependency)!;
      if (finish > start || (finish === start && (!bestPrefix || comparePaths(candidate, bestPrefix) < 0))) {
        start = finish;
        bestPrefix = candidate;
      }
      layer = Math.max(layer, layerById.get(dependency)! + 1);
    }

    const finish = start + task.duration;
    earliest[id] = { start, finish };
    layerById.set(id, layer);
    paths.set(id, [...(bestPrefix ?? []), id]);
    totalDuration = Math.max(totalDuration, finish);
  }

  const layers: string[][] = [];
  for (const id of order) {
    const layer = layerById.get(id)!;
    (layers[layer] ??= []).push(id);
  }
  for (const ids of layers) ids.sort((a, b) => a.localeCompare(b));

  let criticalPath: string[] = [];
  for (const id of order) {
    if (earliest[id].finish !== totalDuration) continue;
    const candidate = paths.get(id)!;
    if (criticalPath.length === 0 || comparePaths(candidate, criticalPath) < 0) criticalPath = candidate;
  }

  return { order, layers, earliest, totalDuration, criticalPath };
}

async function main(args: string[]): Promise<void> {
  if (args.length === 0) fail("usage: bun run src/cli.ts plan INPUT.json");
  if (args[0] !== "plan") fail(`unknown command: ${args[0]}`);
  if (args.length < 2) fail("missing input file");
  if (args.length > 2) fail(`unknown argument or flag: ${args[2]}`);

  let text: string;
  try {
    text = await Bun.file(args[1]).text();
  } catch (error) {
    fail(`cannot read ${JSON.stringify(args[1])}: ${error instanceof Error ? error.message : String(error)}`);
  }

  let input: unknown;
  try {
    input = JSON.parse(text);
  } catch (error) {
    fail(`invalid JSON: ${error instanceof Error ? error.message : String(error)}`);
  }

  console.log(JSON.stringify(plan(validate(input))));
}

try {
  await main(Bun.argv.slice(2));
} catch (error) {
  console.error(`error: ${error instanceof Error ? error.message : String(error)}`);
  process.exit(1);
}

import { afterAll, describe, expect, test } from "bun:test";
import { mkdtemp, rm, writeFile } from "node:fs/promises";
import { join } from "node:path";
import { tmpdir } from "node:os";

const directory = await mkdtemp(join(tmpdir(), "dependency-planner-"));
const cli = join(import.meta.dir, "..", "src", "cli.ts");

afterAll(() => rm(directory, { recursive: true, force: true }));

async function run(input: unknown, ...extra: string[]) {
  const file = join(directory, `${crypto.randomUUID()}.json`);
  await writeFile(file, JSON.stringify(input));
  return Bun.$`bun run ${cli} plan ${file} ${extra}`.quiet().nothrow();
}

describe("dependency planner", () => {
  test("plans deterministic order, layers, times, and lexical critical path", async () => {
    const result = await run({
      tasks: [
        { id: "deploy", duration: 1, dependsOn: ["package"] },
        { id: "test", duration: 3, dependsOn: ["lint"] },
        { id: "build", duration: 3, dependsOn: ["lint"] },
        { id: "package", duration: 2, dependsOn: ["test", "build"] },
        { id: "lint", duration: 1 },
      ],
    });

    expect(result.exitCode).toBe(0);
    expect(JSON.parse(result.stdout.toString())).toEqual({
      order: ["lint", "build", "test", "package", "deploy"],
      layers: [["lint"], ["build", "test"], ["package"], ["deploy"]],
      earliest: {
        lint: { start: 0, finish: 1 },
        build: { start: 1, finish: 4 },
        test: { start: 1, finish: 4 },
        package: { start: 4, finish: 6 },
        deploy: { start: 6, finish: 7 },
      },
      totalDuration: 7,
      criticalPath: ["lint", "build", "package", "deploy"],
    });
  });

  test("supports empty input and zero-duration disconnected tasks", async () => {
    const empty = await run({ tasks: [] });
    expect(JSON.parse(empty.stdout.toString())).toEqual({
      order: [], layers: [], earliest: {}, totalDuration: 0, criticalPath: [],
    });

    const zero = await run({ tasks: [{ id: "z", duration: 0 }, { id: "a", duration: 0 }] });
    expect(JSON.parse(zero.stdout.toString()).criticalPath).toEqual(["a"]);
  });

  test("reports a deterministic concrete cycle", async () => {
    const result = await run({
      tasks: [
        { id: "c", duration: 1, dependsOn: ["a"] },
        { id: "b", duration: 1, dependsOn: ["c"] },
        { id: "a", duration: 1, dependsOn: ["b"] },
      ],
    });
    expect(result.exitCode).not.toBe(0);
    expect(result.stderr.toString()).toContain("a -> b -> c -> a");
  });

  test.each([
    [{}, '"tasks" must be an array'],
    [{ tasks: [{ id: "", duration: 1 }] }, "non-empty string"],
    [{ tasks: [{ id: "a", duration: Number.POSITIVE_INFINITY }] }, "finite non-negative"],
    [{ tasks: [{ id: "a", duration: 1 }, { id: "a", duration: 2 }] }, "duplicate task id"],
    [{ tasks: [{ id: "a", duration: 1, dependsOn: ["b"] }] }, "unknown task"],
    [{ tasks: [{ id: "a", duration: 1, dependsOn: ["a"] }] }, "cannot depend on itself"],
    [{ tasks: [{ id: "a", duration: 1, dependsOn: ["b", "b"] }, { id: "b", duration: 1 }] }, "duplicate id"],
  ])("rejects invalid input", async (input, message) => {
    const result = await run(input);
    expect(result.exitCode).not.toBe(0);
    expect(result.stderr.toString()).toContain(message as string);
  });

  test("rejects invalid JSON and unknown arguments", async () => {
    const file = join(directory, "invalid.json");
    await writeFile(file, "{");
    const invalid = await Bun.$`bun run ${cli} plan ${file}`.quiet().nothrow();
    expect(invalid.exitCode).not.toBe(0);
    expect(invalid.stderr.toString()).toContain("invalid JSON");

    const flag = await run({ tasks: [] }, "--extra");
    expect(flag.exitCode).not.toBe(0);
    expect(flag.stderr.toString()).toContain("unknown argument or flag");
  });
});

# Dependency Planner

A dependency-free TypeScript CLI for Bun that validates a task graph and emits a deterministic execution plan.

## Usage

```sh
bun run src/cli.ts plan INPUT.json
```

Input:

```json
{
  "tasks": [
    { "id": "lint", "duration": 1 },
    { "id": "build", "duration": 3, "dependsOn": ["lint"] }
  ]
}
```

On success, stdout contains one compact JSON object with `order`, `layers`, `earliest`, `totalDuration`, and `criticalPath`. Invalid input, unknown arguments, and dependency cycles produce a non-zero exit status and a message on stderr.

